function UnifySDKHelper:Purchase_CreateOrder(productId, itemId, setJfExtInfo, orderId, orderDec, amount, currency, roleName, roleLv, serverName, callbackUrl)
    print("CreateOrder-----productId:", productId, "   orderId:", orderId, "callbackUrl:", callbackUrl)
    if ClientDataManager:Get():GetGameState() == GameState.Login_GameServer then
        CommonHelper:PlayScreenEffectWaiting(true)
        UnifySDKHelper:Purchase_SubmitRoleInfo(PurchaseRoleInfoData_SubmitType.Purchase)
        UnifySDKHelper:Purchase_Purchase(orderId, orderDec, productId,itemId, amount, currency, roleName, roleLv, serverName, setJfExtInfo,callbackUrl)
    end
end

---@field   sType PurchaseRoleInfoData.SubmitType        @ （1 进入游戏   2 创建角色 3角色升级   其他  充值前统计等）
function UnifySDKHelper:Purchase_SubmitRoleInfo(sType)
    local data = PurchaseRoleInfoData()
    data.submitType = sType
    data.gameRoleName = PlayerDataManager:Get():GetPlayerName() or "1"
    data.gameRoleLevel = PlayerDataManager:Get():GetPlayerLV() or "1"
    data.gameRoleID = PlayerDataManager:Get():GetPlayerRID() or "1"
    data.channelUserId = PlayerDataManager:Get():GetPlayerUID() or "1"
    data.serverName = "1"
    data.serverID = PlayerDataManager:Get():GetPlayerServerID()
    data.gold1 = PlayerDataManager:Get():GetCurrency(CurrencyType.Diamond) or "1"
    data.gold2 = PlayerDataManager:Get():GetCurrency(CurrencyType.Gold) or "1"
    data.gameRoleBalance = "1"
    if  data.serverID ~= nil then
        if ClientDataManager:Get():GetServerInfoByServerId(PlayerDataManager:Get():GetPlayerServerID()) ~= nil then
            data.serverName = ClientDataManager:Get():GetServerInfoByServerId(PlayerDataManager:Get():GetPlayerServerID()):GetName()
        end
    end
    UnifySDKManager:Get():IPurchase():SubmitPurchaseRoleInfo(data)
end

function UnifySDKHelper:Purchase_Purchase(orderId, orderDec, productId, itemId, amount, currency, roleName, roleLv, serverName, serverIdParam, callbackUrl)
    local data = PurchaseOrderInfoData()
    data.goodsID = itemId
    if UnifySDKManager:Get():ISDK():GetChannelID() == "24" then
        data.goodsID = productId
    end
    data.cpOrderID = orderId
    data.quantifier = "个"
    data.extrasParams = serverIdParam
    data.count = 1
    data.price = tonumber(amount)
    data.amount = tonumber(amount)
    data.callbackUrl = callbackUrl
    data.goodsName = orderDec
    data.goodsDesc = orderDec

    data.productId = productId

    data.currency = currency
    data.roleName = roleName
    data.roleLv = roleLv
    data.serverName = serverName
    self.currCpOrderID = orderId
    UnifySDKManager:Get():IPurchase():Purchase(data)
end